#include <iostream>
#include <vector>
#include <algorithm>
#include <climits>
using namespace std;

struct Rect {
    long long x1, y1, x2, y2;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<Rect> r(n);
    long long minX = LLONG_MAX, minY = LLONG_MAX;
    long long maxX = LLONG_MIN, maxY = LLONG_MIN;
    long long totalArea = 0;

    for (auto& p : r) {
        cin >> p.x1 >> p.y1 >> p.x2 >> p.y2;
        if (p.x1 > p.x2) swap(p.x1, p.x2);
        if (p.y1 > p.y2) swap(p.y1, p.y2);

        minX = min(minX, p.x1);
        minY = min(minY, p.y1);
        maxX = max(maxX, p.x2);
        maxY = max(maxY, p.y2);
        totalArea += (p.x2 - p.x1) * (p.y2 - p.y1);
    }

    long long width = maxX - minX;
    long long height = maxY - minY;

    if (width != height || width <= 0 || totalArea != width * height) {
        cout << "NO\n";
        return 0;
    }

    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            long long overlapWidth =
                min(r[i].x2, r[j].x2) - max(r[i].x1, r[j].x1);
            long long overlapHeight =
                min(r[i].y2, r[j].y2) - max(r[i].y1, r[j].y1);

            if (overlapWidth > 0 && overlapHeight > 0) {
                cout << "NO\n";
                return 0;
            }
        }
    }

    cout << "YES\n";
    return 0;
}

#include <iostream>
#include <algorithm>
#include <vector>
using namespace std;

struct Rect {
    long long x1, y1, x2, y2;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    vector<Rect> rectangles(n);
    vector<long long> xs, ys;

    for (auto& r : rectangles) {
        cin >> r.x1 >> r.y1 >> r.x2 >> r.y2;
        if (r.x1 > r.x2) swap(r.x1, r.x2);
        if (r.y1 > r.y2) swap(r.y1, r.y2);

        xs.push_back(r.x1);
        xs.push_back(r.x2);
        ys.push_back(r.y1);
        ys.push_back(r.y2);
    }

    sort(xs.begin(), xs.end());
    xs.erase(unique(xs.begin(), xs.end()), xs.end());
    sort(ys.begin(), ys.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());

    if (xs.back() - xs.front() != ys.back() - ys.front()) {
        cout << "NO\n";
        return 0;
    }

    for (size_t i = 0; i + 1 < xs.size(); ++i) {
        for (size_t j = 0; j + 1 < ys.size(); ++j) {
            int covering = 0;

            for (const auto& r : rectangles) {
                if (r.x1 <= xs[i] && xs[i + 1] <= r.x2 &&
                    r.y1 <= ys[j] && ys[j + 1] <= r.y2) {
                    ++covering;
                }
            }

            if (covering != 1) {
                cout << "NO\n";
                return 0;
            }
        }
    }

    cout << "YES\n";
    return 0;
}

